import type { MetadataRoute } from "next";

// Web app manifest (auto-served at /manifest.webmanifest). Colors mirror the
// design-system tokens --forest / --paper. See ADR-0007.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Shuddha",
    short_name: "Shuddha",
    description:
      "Shuddha — India's curated marketplace for clean, verified brands.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#fafaf7",
    theme_color: "#1b3a2f",
    // Brand icons (generated by scripts/gen-icons.mjs). 192 + 512 PNG maskable
    // satisfy Chromium's installability criteria (beforeinstallprompt).
    icons: [
      { src: "/favicon.ico", sizes: "48x48", type: "image/x-icon" },
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
